$inserted = 0; $errors = [];
foreach ($posts as $p) {
    try {
        $st = db()->prepare('INSERT IGNORE INTO posts (slug, title, category, excerpt, body, date, read_time, published) VALUES (?,?,?,?,?,?,?,1)');
        $st->execute([
            $p['id'], $p['title'], $p['category'], $p['excerpt'],
            json_encode($p['body'], JSON_UNESCAPED_UNICODE),
            $p['date'], $p['read'],
        ]);
        $inserted++;
    } catch (Exception $e) {
        $errors[] = $p['id'] . ': ' . $e->getMessage();
    }
}
json(['inserted' => $inserted, 'errors' => $errors]);